import type { Metadata } from 'next'
import './globals.css'

export const metadata: Metadata = {
  title: 'Market Signal Atlas',
  description: 'Public signals and observed market reactions',
}

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return <html lang="en"><body>{children}</body></html>
}

import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  reactStrictMode: true,
}

export default nextConfig

export type Pack = 'ai_chips' | 'ev' | 'crypto'
export type Asset = 'SPY' | 'QQQ' | 'SOXX' | 'TSLA' | 'BTC' | 'DOGE'
export type Relevance = 'direct' | 'sector' | 'market'

export type AssetLink = { symbol: Asset; relevance: Relevance; rationale: string; benchmark: string }
export type Evidence = { kind: 'source' | 'entity_match' | 'news_cluster'; value: string; url?: string }
export type Signal = {
  id: string; pack: Pack; sourceType: 'social'; occurredAt: string; timePrecision: 'minute' | 'hour';
  entity: { type: 'executive' | 'public_figure'; name: string; handle: string };
  title: string; excerpt: string; canonicalUrl: string; tags: string[]; assetLinks: AssetLink[];
  evidence: Evidence[]; confidence: 'High' | 'Medium'; impactScore: number
}
export type MarketBar = { date: string; SPY: number; QQQ: number; SOXX: number; TSLA: number; BTC: number; DOGE: number }
export type EventMetric = { signalId: string; symbol: Asset; benchmark: string; minus1d: number; day0: number; plus1d: number; plus3d: number; abnormalReturn: number; volumeChange: number; volatilityChange: number }
export type NewsArticle = { id: string; signalId: string; title: string; domain: string; seenAt: string; url: string; attention: number }

'use client'

import { useEffect, useMemo, useState } from 'react'
import { articles, assetLabels, marketBars, metrics, packLabels, signals } from '@/data/market-data'
import type { Asset, Pack, Signal } from '@/types/market'

const packs: Array<Pack | 'all'> = ['ai_chips', 'ev', 'crypto']
const format = (n: number) => `${n >= 0 ? '+' : ''}${n.toFixed(1)}%`
const date = (iso: string) => new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', timeZone: 'UTC' }).format(new Date(iso))

function Sparkline({ asset, selected }: { asset: Asset; selected: Signal }) {
  const values = marketBars.map((bar) => bar[asset])
  const min = Math.min(...values); const max = Math.max(...values); const width = 720; const height = 215
  const points = values.map((value, i) => `${(i / (values.length - 1)) * width},${height - ((value - min) / (max - min)) * (height - 24) - 12}`).join(' ')
  const markers = signals.filter((s) => s.assetLinks.some((l) => l.symbol === asset)).slice(0, 6)
  return <div className="chart-wrap">
    <div className="chart-y"><span>{max.toFixed(0)}</span><span>{((max + min) / 2).toFixed(0)}</span><span>{min.toFixed(0)}</span></div>
    <svg className="chart" viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none" role="img" aria-label={`${asset} indexed price chart`}>
      {[20, 95, 170].map((y) => <line key={y} x1="0" y1={y} x2={width} y2={y} className="grid-line" />)}
      <polyline points={points} fill="none" stroke="#80ffb4" strokeWidth="3" vectorEffect="non-scaling-stroke" />
      {markers.map((marker, i) => <g key={marker.id} className={marker.id === selected.id ? 'marker active' : 'marker'}><line x1={70 + i * 105} y1="10" x2={70 + i * 105} y2="194" /><circle cx={70 + i * 105} cy={30 + (i % 3) * 33} r="6" /></g>)}
    </svg>
    <div className="chart-x"><span>Jan</span><span>Mar</span><span>May</span><span>Jul</span><span>Sep</span><span>Nov</span></div>
  </div>
}

export default function Dashboard() {
  const [pack, setPack] = useState<Pack>('ai_chips')
  const [asset, setAsset] = useState<Asset>('SOXX')
  const [selectedId, setSelectedId] = useState('ai-1')

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    const queriedPack = params.get('pack') as Pack | null; const queriedAsset = params.get('asset') as Asset | null; const queriedSignal = params.get('signal')
    if (queriedPack && packLabels[queriedPack]) setPack(queriedPack)
    if (queriedAsset && assetLabels.includes(queriedAsset)) setAsset(queriedAsset)
    if (queriedSignal && signals.some((signal) => signal.id === queriedSignal)) setSelectedId(queriedSignal)
  }, [])

  const filtered = useMemo(() => signals.filter((signal) => signal.pack === pack && signal.assetLinks.some((link) => link.symbol === asset)), [pack, asset])
  const safeSelected = filtered.find((signal) => signal.id === selectedId) ?? filtered[0] ?? signals.find((signal) => signal.pack === pack) ?? signals[0]
  const selectedMetric = metrics.find((metric) => metric.signalId === safeSelected.id)!
  const selectedArticles = articles.filter((article) => article.signalId === safeSelected.id)
  const packSignals = signals.filter((signal) => signal.pack === pack)
  const packMetrics = metrics.filter((metric) => packSignals.some((signal) => signal.id === metric.signalId))
  const avgAbnormal = packMetrics.reduce((sum, metric) => sum + Math.abs(metric.abnormalReturn), 0) / packMetrics.length
  const highReaction = packSignals.filter((signal) => signal.impactScore >= 75).length

  const choose = (signal: Signal) => { setSelectedId(signal.id); setAsset(signal.assetLinks[0].symbol); setPack(signal.pack); sync(signal.pack, signal.assetLinks[0].symbol, signal.id) }
  const sync = (nextPack: Pack, nextAsset: Asset, nextSignal = selectedId) => window.history.replaceState(null, '', `?pack=${nextPack}&asset=${nextAsset}&signal=${nextSignal}`)
  const changePack = (next: Pack) => { const next = signals.find((signal) => signal.pack === next)!; setPack(next); setAsset(next.assetLinks[0].symbol); setSelectedId(next.id); sync(next, next.assetLinks[0].symbol, next.id) }
  const changeAsset = (next: Asset) => { const match = signals.find((signal) => signal.pack === pack && signal.assetLinks.some((link) => link.symbol === next)) ?? signals.find((signal) => signal.pack === pack)!; setAsset(next); setSelectedId(match.id); sync(pack, next, match.id) }

  return <main>
    <header className="topbar"><a className="brand" href="/"><span className="brand-mark">↗</span><span>MARKET<br /><b>SIGNAL ATLAS</b></span></a><div className="header-meta"><span className="live-dot" /> Fixed case-study data <span className="divider" /> UTC</div></header>
    <section className="intro"><div><p className="eyebrow">PUBLIC SIGNAL × OBSERVED MARKET RESPONSE</p><h1>Trace the context<br /><em>behind market movement.</em></h1><p className="subhead">Explore publicly available signals alongside observed price reaction and information attention. Not investment advice.</p></div><div className="intro-note"><span>RESEARCH MODE</span><strong>12</strong><p>curated public<br />case studies</p></div></section>

    <section className="filters" aria-label="Dashboard filters"><div className="filter-group"><span>Signal Pack</span><div className="segmented">{packs.map((item) => <button key={item} onClick={() => changePack(item as Pack)} className={pack === item ? 'chosen' : ''}>{packLabels[item as Pack]}</button>)}</div></div><div className="filter-group"><span>Asset</span><select value={asset} onChange={(event) => changeAsset(event.target.value as Asset)}>{assetLabels.map((item) => <option key={item}>{item}</option>)}</select></div><div className="filter-group range"><span>Period</span><button className="range-button">All fixed cases <span>⌄</span></button></div></section>

    <section className="kpis"><Kpi label="SIGNALS IN VIEW" value={String(filtered.length)} hint={`${packLabels[pack]} · ${asset}`} /><Kpi label="HIGH REACTION" value={String(highReaction)} hint="Impact score ≥ 75" accent /><Kpi label="AVG. ABS. EXCESS RETURN" value={format(avgAbnormal)} hint={`vs. ${selectedMetric.benchmark}`} /><Kpi label="NEWS ATTENTION" value={`${selectedArticles.reduce((sum, item) => sum + item.attention, 0)} pts`} hint="Fixed case-study index" /></section>

    <section className="main-grid"><div className="timeline-panel panel"><div className="panel-head"><div><p className="micro">MARKET TIMELINE</p><h2>{asset} <span>indexed price</span></h2></div><div className="legend"><i /> Price <b /> Signal</div></div><Sparkline asset={asset} selected={safeSelected} /><div className="timeline-foot"><span>Price indexed to 100</span><span>{signals.filter((signal) => signal.assetLinks.some((link) => link.symbol === asset)).length} annotated signals</span></div></div><aside className="ranking panel"><div className="panel-head"><div><p className="micro">IMPACT RANKING</p><h2>Observed reaction</h2></div><span className="mini-badge">TOP CASES</span></div>{packSignals.slice().sort((a, b) => b.impactScore - a.impactScore).slice(0, 4).map((signal, index) => <button onClick={() => choose(signal)} className={`rank-row ${safeSelected.id === signal.id ? 'selected' : ''}`} key={signal.id}><span className="rank-number">0{index + 1}</span><span className="rank-title">{signal.title}<small>{signal.assetLinks[0].symbol} · {signal.entity.name}</small></span><strong>{signal.impactScore}</strong></button>)}</aside></section>

    <section className="detail-grid"><div className="feed panel"><div className="panel-head"><div><p className="micro">SIGNAL FEED</p><h2>Selected universe</h2></div><span className="count">{filtered.length} cases</span></div>{filtered.length ? filtered.map((signal) => <button className={`feed-row ${signal.id === safeSelected.id ? 'selected' : ''}`} onClick={() => choose(signal)} key={signal.id}><span className="feed-date">{date(signal.occurredAt)}<small>UTC</small></span><span className="feed-copy"><b>{signal.title}</b><span>{signal.entity.name} · {signal.tags.slice(0, 2).join(' / ')}</span></span><span className={`score ${signal.impactScore >= 75 ? 'hot' : ''}`}>{signal.impactScore}</span></button>) : <div className="empty">No fixed cases pair this asset with this pack.<br />Choose an annotated asset.</div>}</div>
      <article className="detail panel"><div className="detail-top"><div><p className="micro">SIGNAL DETAIL <span className="fixed">FIXED CASE STUDY</span></p><h2>{safeSelected.title}</h2><p className="byline">{safeSelected.entity.name} · {safeSelected.entity.handle} · {new Date(safeSelected.occurredAt).toISOString().replace('T', ' ').slice(0, 16)} UTC</p></div><a className="source-link" href={safeSelected.canonicalUrl} target="_blank" rel="noreferrer">View source ↗</a></div><blockquote>“{safeSelected.excerpt}”</blockquote><div className="tags">{safeSelected.tags.map((tag) => <span key={tag}>{tag}</span>)}</div><div className="why"><span>WHY LINKED?</span><p><b>{safeSelected.assetLinks[0].symbol}</b> · {safeSelected.assetLinks[0].relevance} — {safeSelected.assetLinks[0].rationale}</p></div><div className="reaction"><div className="reaction-head"><div><p className="micro">MARKET REACTION</p><h3>Event window <span>vs. {selectedMetric.benchmark}</span></h3></div><strong className={selectedMetric.abnormalReturn >= 0 ? 'positive' : 'negative'}>{format(selectedMetric.abnormalReturn)}<small>excess return</small></strong></div><div className="metric-table">{[['−1D', selectedMetric.minus1d], ['0D', selectedMetric.day0], ['+1D', selectedMetric.plus1d], ['+3D', selectedMetric.plus3d]].map(([label, value]) => <div key={String(label)}><span>{label}</span><b className={Number(value) >= 0 ? 'positive' : 'negative'}>{format(Number(value))}</b></div>)}</div><p className="method-note">{asset === 'BTC' || asset === 'DOGE' ? 'UTC daily price points; BTC is the DOGE comparison reference.' : 'US equity trading day; after-close or holiday signals map to the next trading day.'}</p></div></article></section>

    <section className="news panel"><div className="panel-head"><div><p className="micro">NEWS ATTENTION</p><h2>Context around this signal</h2></div><span className="attention-value">{selectedArticles.reduce((sum, article) => sum + article.attention, 0)} <small>attention pts</small></span></div><div className="news-content"><div className="attention-bars">{Array.from({ length: 12 }, (_, index) => <i key={index} style={{ height: `${18 + ((index * 17 + safeSelected.impactScore) % 75)}%` }} className={index > 6 ? 'active' : ''} />)}<span>−3D</span><span>Signal</span><span>+3D</span></div><div className="headlines">{selectedArticles.map((article) => <a key={article.id} href={article.url} target="_blank" rel="noreferrer"><span>{article.domain}</span>{article.title}<b>↗</b></a>)}</div></div></section>

    <section className="methodology"><div><p className="micro">METHODOLOGY</p><h2>Explore patterns, not causality.</h2></div><div className="method-columns"><p>Signals are curated public posts with a source link, recorded UTC time, and documented asset-link rationale. Price reaction is observed around the event; it does not establish cause.</p><p><b>Data boundaries</b><br />US equities use New York trading days. BTC/DOGE use UTC daily data. News headlines are fixed case-study context, not live coverage.</p></div></section>
    <footer>Market Signal Atlas · Research and educational demonstration only · Not investment advice</footer>
  </main>
}

function Kpi({ label, value, hint, accent = false }: { label: string; value: string; hint: string; accent?: boolean }) { return <article className={`kpi ${accent ? 'accent' : ''}`}><p>{label}</p><strong>{value}</strong><span>{hint}</span></article> }

